'use client'

import * as React from 'react'
import { OrbComposing } from '@/components/orb/thinking/index'
import type { ThinkingOrbSurface } from '@/components/orb/thinking/index'

export interface DemoProps {
  surface?: ThinkingOrbSurface
  size?: number
  speed?: number
  scale?: number
  playback?: 'play' | 'pause'
}

export default function Demo({ surface = 'auto', size = 240, speed = 1, scale = 0.72, playback = 'play' }: DemoProps) {
  return (
    <div className="flex size-full min-h-[300px] flex-col items-center justify-center p-6">
      <OrbComposing surface={surface} size={size} speed={speed} scale={scale} playback={playback} />
    </div>
  )
}
